<?php require 'app.php'; if(u())go('index.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim($_POST['email']??''));$q=db()->prepare("SELECT id,full_name,email,password_hash,is_platform_owner,status FROM users WHERE lower(email)=?");$q->execute([$email]);$x=$q->fetch();if($x&&$x['status']==='active'&&password_verify($_POST['password']??'',$x['password_hash'])){session_regenerate_id(true);if($x['is_platform_owner'])$_SESSION['user']=$x+['role_key'=>'owner','school_id'=>null];else{$m=db()->prepare("SELECT m.school_id,m.role_key,s.name school_name FROM memberships m JOIN schools s ON s.id=m.school_id WHERE m.user_id=? AND m.status='active' AND s.status='active' LIMIT 1");$m->execute([$x['id']]);$mem=$m->fetch();if(!$mem){$err='No active school membership found.';}else $_SESSION['user']=$x+$mem;}if(!$err)go('index.php');}else $err='Invalid email or password.';}ob_start();?><div class="panel" style="max-width:430px;margin:50px auto"><h2>Sign in</h2><?php if($err):?><p class="danger"><?=h($err)?></p><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button>Sign in</button></form><p class="muted">Contact your school administrator if you need an account.</p></div><?php $b=ob_get_clean();page('Welcome',$b);
